script.v:
"""
                    rm -rf pkgs/${platform}
                    mkdir -p pkgs/${platform}
                    mv ${platform}/rpmbuild/RPMS/\$(arch)/*rpm pkgs/${platform} || true
                    mv ${platform}/couchdb/*.deb pkgs/${platform} || true
                  """

value.v:
logger: {
  format: Raw
  output: Stdout
  level: debug
}
config: [
  {
    node: {
      name: clouseau1
      domain: 127.0.0.1
    }
    clouseau: {
      commit_interval_secs: 1
    }
  }
]
